/* Геометрические схемы: стрелки строятся из координат, графики — по формулам. */
const DIAGRAM_CAPTIONS={
 m01:'Путь S идёт по траектории. Перемещение Δr соединяет A и B и не зависит от формы промежуточного пути.',
 m02:'В показанном разгоне v и aτ направлены по касательной. Нормальная составляющая an поворачивает скорость, а полное ускорение a — сумма двух составляющих.',
 m03:'Вид вдоль оси: положительный поворот против часовой стрелки. Угловая скорость направлена к наблюдателю; при разгоне угловое ускорение направлено так же.',
 m06:'Брусок скользит вниз. Сила тяжести направлена вертикально, реакция — перпендикулярно плоскости, трение — вверх вдоль неё.',
 m08:'Сила составляет угол α с перемещением. Работа постоянной силы равна F|Δr| cos α: перпендикулярная составляющая работы не совершает.',
 m10:'В теореме Штейнера оси параллельны, первая проходит через центр масс C. Плечо l — перпендикуляр от O к линии действия силы, а не расстояние до точки её приложения.',
 m11:'Показана касательная сила при положительном малом повороте. Дуга dS = r dφ в этом направлении; работа равна Mz dφ. При тормозящем моменте работа отрицательна.',
 m15:'Для формулы пресса поршни рассматриваются на одной высоте. Сила Архимеда направлена вверх, сила тяжести — вниз; V — объём погружённой части тела.',
 m17:'Горизонтальная трубка: в узком сечении идеальный стационарный поток быстрее. На одной линии тока при этом статическое давление ниже.',
 m18:'Стрелки показывают скорости слоёв полностью развитого ламинарного потока. У стенок v = 0, на оси скорость максимальна; концы стрелок образуют параболу.',
 m20:'Слева показаны сила тяжести и её касательная возвращающая составляющая. Для пружины x отсчитывают от равновесия; стрелка F = −kx показывает возвращающую равнодействующую.',
 m22:'Сплошная линия — смещение, пунктир — огибающие ±A₀e⁻ᵝᵗ. Период между соседними циклами постоянен, амплитуда уменьшается.',
 m23:'Кривые рассчитаны по формуле установившейся амплитуды при одинаковых массе, жёсткости и внешней силе. При большем затухании пик ниже и сдвинут влево от ω₀.'
};
const CLASSROOM=Object.fromEntries(LESSON_DATA.filter(n=>DIAGRAM_CAPTIONS[n.id]).map(n=>[n.id,{caption:DIAGRAM_CAPTIONS[n.id]}]));
function diagramPicture(key,title,draw){
 const colors={green:'var(--green)',orange:'var(--orange)',gray:'#89958d',blue:'#547e91'};
 const marker=c=>'arrow-'+key+'-'+c;
 const line=(x1,y1,x2,y2,c='green',arrow=true,dash=false,both=false)=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${colors[c]}" stroke-width="2.5" ${dash?'stroke-dasharray="6 5"':''} ${arrow?'marker-end="url(#'+marker(c)+')"':''} ${both?'marker-start="url(#'+marker(c)+')"':''}/>`;
 const path=(d,c='green',arrow=false,dash=false)=>`<path d="${d}" fill="none" stroke="${colors[c]}" stroke-width="2.5" ${dash?'stroke-dasharray="6 5"':''} ${arrow?'marker-end="url(#'+marker(c)+')"':''}/>`;
 const text=(x,y,s,c='var(--ink)',size=20)=>`<text x="${x}" y="${y}" fill="${c}" font-size="${size}">${esc(s)}</text>`;
 const dot=(x,y,r=5)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="var(--green)"/>`;
 const circle=(x,y,r,c='green')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="none" stroke="${colors[c]}" stroke-width="2.5"/>`;
 const box=(x,y,w,h,fill='none',rotation=0)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="5" fill="${fill}" stroke="var(--green)" stroke-width="2.5" ${rotation?'transform="rotate('+rotation+' '+(x+w/2)+' '+(y+h/2)+')"':''}/>`;
 return `<svg class="lesson-svg" viewBox="0 0 480 320" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title><defs>${Object.entries(colors).map(([c,v])=>`<marker id="${marker(c)}" viewBox="0 0 10 10" refX="8.5" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="${v}"/></marker>`).join('')}</defs><g font-family="Nunito,sans-serif" stroke-linecap="round" stroke-linejoin="round">${draw({line,path,text,dot,circle,box})}</g></svg>`;
}
function lessonDiagram(id){
 const pic=(suffix,title,draw)=>diagramPicture(id+'-'+suffix,title,draw);
 if(id==='m01')return pic('path','Путь, перемещение и радиус-векторы',({line,path,text,dot})=>line(40,250,445,250,'gray')+line(40,250,40,25,'gray')+line(40,250,120,190,'gray')+line(40,250,390,80,'gray',true,true)+path('M120 190 C160 40 280 220 390 80','orange')+line(120,190,390,80)+dot(120,190)+dot(390,80)+text(21,276,'O')+text(445,278,'x')+text(18,28,'y')+text(103,220,'A')+text(400,72,'B')+text(65,208,'r₁')+text(210,200,'r₂')+text(300,181,'Δr')+text(210,102,'Путь S', 'var(--orange)'));
 if(id==='m02')return pic('acceleration','Касательная и нормальная составляющие ускорения',({line,path,text,dot})=>path('M35 180 C100 90 145 90 200 90 C300 90 370 180 420 240','gray')+line(200,90,330,90,'orange')+line(200,90,200,220,'blue')+line(200,90,330,220)+line(330,90,330,220,'gray',false,true)+line(200,220,330,220,'gray',false,true)+dot(200,90)+text(320,69,'aτ')+text(165,190,'an')+text(344,228,'a')+text(350,111,'v →')+text(215,49,'Точка на траектории','var(--muted)',18));
 if(id==='m03')return pic('rotation','Направление угловой скорости при повороте против часовой стрелки',({line,path,text,dot,circle})=>circle(195,155,105)+path('M300 155 A105 105 0 0 0 195 50','orange',true)+line(195,155,300,155,'gray',false)+line(195,155,270,80)+path('M235 155 A40 40 0 0 0 223.3 126.7','gray')+circle(195,155,12)+dot(195,155,3)+dot(270,80)+text(248,142,'φ')+text(215,105,'R')+text(316,153,'ω — к нам')+text(315,182,'⊙ вдоль оси','var(--muted)',18)+text(80,290,'При разгоне ε направлено так же','var(--muted)',18));
 if(id==='m06')return pic('forces','Силы на скользящем вниз бруске',({line,path,text,box})=>path('M55 245 L410 80 L410 245 Z','gray')+box(211.6,118.9,50,40,'var(--white)',-24.93)+line(236.6,138.9,236.6,260,'orange')+line(236.6,138.9,192,43)+line(236.6,138.9,334,94)+line(236.6,138.9,150,179,'gray',true,true)+path('M105 245 A50 50 0 0 0 100.3 223.9','gray')+text(249,273,'mg')+text(172,35,'N')+text(343,91,'Fтр')+text(120,177,'v')+text(113,233,'α'));
 if(id==='m08')return pic('work','Угол силы и перемещения при вычислении работы',({line,path,text,dot})=>line(70,230,420,230)+line(70,230,340,75,'orange')+line(340,75,340,230,'gray',false,true)+path('M130 230 A60 60 0 0 0 122 200','gray')+dot(70,230)+text(350,70,'F')+text(364,262,'Δr')+text(140,208,'α')+text(122,300,'A = F|Δr| cos α'));
 if(id==='m10')return pic('axes','Параллельные оси в теореме Штейнера',({line,text,dot,box})=>box(65,140,330,38,'#f3f1e8')+line(230,245,230,35,'blue')+line(365,245,365,35,'orange')+dot(230,159)+line(230,263,365,263,'gray',true,false,true)+text(242,35,'zc')+text(378,35,'z')+text(241,199,'C')+text(289,287,'a')+text(44,68,'I = Ic + ma²'))+pic('torque','Плечо силы перпендикулярно линии её действия',({line,path,text,dot})=>line(350,310,215,55,'gray',false,true)+line(75,235,310,235)+line(310,235,225,74,'orange')+line(75,235,258.5,137.8,'blue',false)+line(310,235,433,235,'gray',false,true)+path('M350 235 A40 40 0 0 0 291.3 199.6','gray')+path('M253.8 129 L245 133.7 L249.7 142.5','blue')+dot(75,235)+dot(310,235)+text(53,260,'O')+text(180,261,'r')+text(155,173,'l')+text(206,62,'F')+text(333,200,'α')+text(343,291,'M = Fl'));
 if(id==='m11')return pic('rotation-work','Работа касательной силы при малом повороте',({line,path,text,dot})=>line(80,230,310,230)+line(80,230,306.5,190,'gray',false,true)+path('M310 230 A230 230 0 0 0 306.5 190','orange',true)+line(310,230,310,65)+path('M125 230 A45 45 0 0 0 124.3 222.2','gray')+dot(80,230)+dot(310,230)+text(57,254,'O')+text(188,256,'r')+text(322,70,'Fτ')+text(333,185,'dS')+text(131,215,'dφ')+text(125,300,'dA = Mz dφ'));
 if(id==='m15')return pic('press','Гидравлический пресс с поршнями на одной высоте',({line,path,text,box})=>'<path d="M55 120 H135 V230 H265 V120 H420 V265 H55 Z" fill="#edf2f4"/>'+path('M55 50 V265 H420 V50 M135 50 V230 H265 V50')+box(55,110,80,10,'#e4e6dc')+box(265,110,155,10,'#e4e6dc')+line(95,30,95,105,'orange')+line(342,108,342,25)+line(135,120,265,120,'gray',false,true)+text(55,27,'F₁')+text(353,35,'F₂')+text(78,153,'S₁')+text(333,153,'S₂')+text(156,101,'Одна высота','var(--muted)',16)+text(199,253,'p')+text(130,307,'F₁/S₁ = F₂/S₂'))+pic('buoyancy','Сила Архимеда и сила тяжести погружённого тела',({line,path,text,box})=>'<rect x="70" y="100" width="330" height="155" rx="6" fill="#edf2f4"/>'+path('M70 80 V255 H400 V80','gray')+line(70,100,400,100,'blue',false)+box(205,130,90,65,'var(--white)')+line(250,162,250,35)+line(250,162,250,280,'orange')+text(267,45,'FA')+text(269,288,'mg')+text(215,171,'V')+text(85,89,'Жидкость','var(--muted)',18));
 if(id==='m17')return pic('flow','Непрерывность и давление в горизонтальной трубке',({line,path,text})=>path('M35 80 H170 C230 80 240 125 300 125 H440 M35 240 H170 C230 240 240 195 300 195 H440')+line(100,80,100,240,'gray',false,true)+line(360,125,360,195,'gray',false,true)+line(55,160,145,160)+line(315,160,433,160)+text(40,59,'S₁, p₁')+text(305,105,'S₂, p₂')+text(110,216,'v₁')+text(370,225,'v₂')+text(70,292,'S₁v₁ = S₂v₂;   p₁ > p₂'));
 if(id==='m18')return pic('profile','Параболический профиль скорости жидкости',({line,path,text})=>{let body=path('M45 70 H430 M45 230 H430','gray')+line(45,150,430,150,'gray',false,true)+path('M100 70 Q420 150 100 230','orange');for(const y of [90,120,150,180,210])body+=line(100,y,100+160*(1-(y-150)**2/80**2),y);return body+line(448,150,448,70,'gray',true,false,true)+text(109,54,'v = 0')+text(109,257,'v = 0')+text(276,155,'vmax')+text(454,119,'R')+text(95,302,'v(r) ∝ R² − r²');});
 if(id==='m20')return pic('pendulum','Математический маятник: смещение и возвращающая составляющая силы',({line,path,text,dot,circle})=>line(155,35,325,35,'gray',false)+line(240,45,240,235,'gray',false,true)+line(240,45,311.8,199.1,'gray',false)+path('M240 100 A55 55 0 0 0 263.2 94.8','orange')+circle(311.8,199.1,13)+dot(240,45)+line(311.8,199.1,311.8,281,'orange')+line(311.8,199.1,242,231.7)+text(275,101,'α')+text(289,124,'l')+text(324,283,'mg')+text(212,253,'Fτ')+text(42,130,'Fτ = −mg sin α','var(--ink)',18))+pic('spring','Пружинный маятник: координата от равновесия',({line,path,text,box})=>line(145,35,335,35,'gray',false)+path('M240 35 V65 l-20 10 40 16 -40 16 40 16 -40 16 40 16 -20 10 V205')+line(65,190,385,190,'gray',false,true)+box(208,205,64,45,'var(--white)')+line(240,227,240,140,'orange')+line(350,190,350,227,'blue',true,false,true)+text(255,147,'F = −kx')+text(365,218,'x')+text(55,180,'x = 0','var(--muted)',18));
 if(id==='m22')return pic('damped','Затухающая синусоида и её огибающие',({line,path,text})=>{let body=line(60,275,60,30,'gray')+line(40,150,445,150,'gray');for(const sign of [-1,1])body+=path(Array.from({length:121},(_,i)=>[60+i*3,150+sign*80*Math.exp(-i*3/170)]).map((p,i)=>(i?'L':'M')+p.join(' ')).join(' '),'orange',false,true);body+=path(Array.from({length:181},(_,i)=>[60+i*2,150-80*Math.exp(-i*2/170)*Math.cos(i*2/19)]).map((p,i)=>(i?'L':'M')+p.join(' ')).join(' '));return body+text(32,29,'x')+text(447,174,'t')+text(18,73,'A₀')+text(195,47,'A(t) = A₀e⁻ᵝᵗ','var(--orange)',18);});
 if(id==='m23')return pic('resonance','Амплитуда вынужденных колебаний при двух коэффициентах затухания',({line,path,text})=>{let body=line(60,255,60,27,'gray')+line(60,255,445,255,'gray')+line(260,255,260,35,'gray',false,true);for(const [beta,c] of [[0.10,'green'],[0.45,'orange']])body+=path(Array.from({length:361},(_,i)=>{const u=i/200;return [60+200*u,255-32/Math.sqrt((1-u*u)**2+4*beta*beta*u*u)];}).map((p,i)=>(i?'L':'M')+p.join(' ')).join(' '),c);return body+text(29,30,'A')+text(443,279,'Ω')+text(246,284,'ω₀')+text(285,86,'Малое β','var(--green)',18)+text(105,188,'Большое β','var(--orange)',18);});
 return '';
}
function classroomScene(t){const data=CLASSROOM[t.id];return data?`<section class="classroom-scene"><h2>Схема</h2><figure>${lessonDiagram(t.id)}<figcaption>${esc(data.caption)}</figcaption></figure></section>`:'';}
